mapper.update:
CREATE TABLE ${schema}.${tempTableName} AS
SELECT

    ${col}

ST_Multi(ST_CollectionExtract(ST_MakeValid(geom), #{dimension}))::geometry(${postgisGeometryType}, ${srid}) AS geom
FROM ${schema}.${table}

CREATE TABLE ${schema}.${newTableName} AS
SELECT row_number() OVER () AS serial_id,

    ${col}


    ST_Transform(geom, ${targetSrid})::geometry(${postgisGeometryType}, ${targetSrid}) AS geom

geom::geometry(${postgisGeometryType}, ${originSrid})
FROM ${schema}.${tableName}

CREATE TABLE ${schema}.${resultTableName} AS
SELECT

    ${col}

ST_Transform(geom, #{targetSrid})::geometry(${postgisGeometryType}, ${targetSrid}) AS geom
FROM ${schema}.${sourceTable}
